                <thead>
                    <tr>
                        <th colspan="2" style="background-color:#fffbeb;color:#92400e;padding:10px 15px;text-align:left;font-size:15px;border-bottom:2px solid #f59e0b;">Detalles del pago</th>
                    </tr>
