                    </tr>
                    <tr style="border-bottom:1px solid #e5e7eb;background-color:#f9fafb;">
                        <td style="padding:10px 15px;color:#6b7280;font-weight:600;">Referencia de pago</td>
                        <td style="padding:10px 15px;">{{payment_reference}}</td>
                    </tr>
                    <tr style="border-bottom:1px solid #e5e7eb;">
                        <td style="padding:10px 15px;color:#6b7280;font-weight:600;">Monto</td>
                        <td style="padding:10px 15px;font-size:18px;font-weight:bold;color:#92400e;">{{amount}} {{currency}}</td>
                    </tr>
                    <tr>
                        <td style="padding:10px 15px;color:#6b7280;font-weight:600;">Metodo de pago</td>
                        <td style="padding:10px 15px;">Efectivo</td>
                    </tr>
                </tbody>
            </table>

            <div style="background-color:#fffbeb;border-left:4px solid #f59e0b;padding:15px;margin:20px 0;border-radius:0 4px 4px 0;">
                <p style="margin:0 0 8px;font-weight:600;color:#92400e;">Proximos pasos</p>
