  VALUES (47, 'LICENSE_GENERATED', 'Licencia comercial generada', 'Licence commerciale générée', 'Commercial license generated', 'Su licencia comercial {{license_ref}} está disponible', 'Votre licence commerciale {{license_ref}} est disponible', 'Your commercial license {{license_ref}} is available', 'Email enviado cuando se genera una licencia comercial, con PDF adjunto', 'Email envoyé lors de la génération d''une licence commerciale, avec PDF joint', 'Email sent when a commercial license is generated, with PDF attachment', NULL, '[{"name": "company_name", "example": "Tienda Hermionne", "required": true, "description": "Nombre de la empresa"}, {"name": "license_ref", "example": "LIC-2026-A1B2C3D4", "required": true, "description": "Referencia de la licencia"}, {"name": "fiscal_year", "example": "2026", "required": true, "description": "Año fiscal"}, {"name": "nif", "example": "PE-8253", "required": false, "description": "NIF o Nº Registro"}, {"name": "total_amount", "example": "170,750", "required": true, "description": "Total obligaciones"}, {"name": "status", "example": "Pendiente", "required": true, "description": "Estado de la licencia"}]', 'license', true, '2026-03-19T12:05:47.293312+00:00'::timestamptz, '2026-03-19T12:05:47.293312+00:00'::timestamptz, NULL, NULL, '<h2>Licencia Comercial Generada</h2>
<p>Estimado/a <strong>{{company_name}}</strong>,</p>
<p>Su licencia comercial para el año fiscal <strong>{{fiscal_year}}</strong> ha sido generada correctamente.</p>
<table style="width:100%;border-collapse:collapse;margin:16px 0;">
  <tr><td style="padding:6px 12px;background:#f5f5f5;font-weight:bold;">Referencia</td><td style="padding:6px 12px;">{{license_ref}}</td></tr>
  <tr><td style="padding:6px 12px;background:#f5f5f5;font-weight:bold;">NIF / Nº Registro</td><td style="padding:6px 12px;">{{nif}}</td></tr>
  <tr><td style="padding:6px 12px;background:#f5f5f5;font-weight:bold;">Total Obligaciones</td><td style="padding:6px 12px;">{{total_amount}} XAF</td></tr>
  <tr><td style="padding:6px 12px;background:#f5f5f5;font-weight:bold;">Estado</td><td style="padding:6px 12px;">{{status}}</td></tr>
</table>
<p>Encontrará el documento PDF adjunto a este correo. También puede descargarlo desde su panel en la plataforma Facil.</p>
<p><strong>AVISO:</strong> Este documento es un justificante provisional que acredita que la licencia comercial oficial se encuentra en proceso de edición.</p>
<p>Atentamente,<br>Dirección General de Impuestos — Guinea Ecuatorial</p>')
