  VALUES (56, 'obligation_overdue', 'Obligaciones Vencidas', 'Obligations en Retard', 'Overdue Obligations', 'Obligaciones vencidas - {{company_name}}', 'Obligations en retard - {{company_name}}', 'Overdue obligations - {{company_name}}', NULL, NULL, NULL, NULL, '["user_name", "company_name", "obligations_count", "total_amount"]', 'fiscal_alerts', true, '2026-04-21T08:18:45.221451+00:00'::timestamptz, '2026-04-21T08:18:45.221451+00:00'::timestamptz, NULL, NULL, '<div style="font-family:Arial,sans-serif;max-width:600px;margin:0 auto">
