  VALUES (57, 'obligation_penalty_applied', 'Penalidad Aplicada', 'Penalite Appliquee', 'Penalty Applied', 'Penalidad aplicada - {{company_name}}', 'Penalite appliquee - {{company_name}}', 'Penalty applied - {{company_name}}', NULL, NULL, NULL, NULL, '["user_name", "company_name", "penalty_total", "obligations_affected"]', 'fiscal_alerts', true, '2026-04-21T08:18:45.221451+00:00'::timestamptz, '2026-04-21T08:18:45.221451+00:00'::timestamptz, NULL, NULL, '<div style="font-family:Arial,sans-serif;max-width:600px;margin:0 auto">
